.utk-container {
    position: absolute;
    bottom: 0; left: 0;
    width: var(--v-width, 100%);
    height: var(--v-height, 60px);
    background: {{PRIMARY_BG}};
    display: flex;
    align-items: stretch;
    overflow: hidden;
    border: {{BORDER_WIDTH}}px solid {{BORDER_COLOR}};
    border-radius: {{BORDER_RADIUS}}px;
    box-shadow: {{BOX_SHADOW}};
    font-family: '{{FONT_FAMILY}}', sans-serif;
    opacity: 0;
    transform: translateY(80px);
    box-sizing: border-box;
    --wiper-w: 150px;
}
.utk-wiper {
    position: absolute;
    left: 0; top: 0; bottom: 0;
    min-width: 60px;
    padding: 0 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: {{WIPER_BG}};
    box-shadow: 8px 0 20px rgba(0,0,0,0.55);
    border-radius: {{BORDER_RADIUS}}px {{BORDER_RADIUS}}px {{BORDER_RADIUS}}px {{BORDER_RADIUS}}px;
    z-index: 5;
    overflow: hidden;
    box-sizing: border-box;
    white-space: nowrap;
}
.utk-gleam {
    position: absolute; top: 0; left: -120%;
    width: 60%; height: 100%;
    background: linear-gradient(90deg,rgba(255,255,255,0) 0%,rgba(255,255,255,0.28) 50%,rgba(255,255,255,0) 100%);
    transform: skewX(-20deg);
    animation: utk-gleam-anim 3s infinite ease-in-out;
    pointer-events: none;
}
@keyframes utk-gleam-anim {
    0%,45% { left: -120%; }
    100% { left: 160%; }
}
.utk-wiper-text {
    font-size: {{WIPER_FONT_SIZE}}px;
    font-weight: {{WIPER_FONT_WEIGHT}};
    font-family: '{{WIPER_FONT}}', sans-serif;
    color: {{WIPER_TEXT_COLOR}};
    letter-spacing: {{WIPER_LETTER_SPACING}}px;
    position: relative; z-index: 1;
    transition: opacity 0.18s ease;
}
/* ---- wiper CSS-class-based animations (keyframe names są re-scopowane przez renderer) ---- */
.utk-wiper.utk-move-right {
    animation: utk-slide-right 1s linear forwards;
}
.utk-wiper.utk-snap-back {
    animation: utk-slide-back 0.5s ease-in-out forwards;
}
@keyframes utk-slide-right {
    0%   { left: 0; }
    100% { left: calc(var(--v-width, 100%) - var(--wiper-w, 150px)); }
}
@keyframes utk-slide-back {
    0%   { left: calc(var(--v-width, 100%) - var(--wiper-w, 150px)); }
    100% { left: 0; }
}
/* ---- body / track ---- */
.utk-body {
    flex: 1;
    overflow: hidden;
    position: relative;
    display: flex;
    align-items: center;
}
.utk-track-wrap {
    position: absolute; inset: 0;
    display: none;
    align-items: center;
    overflow: hidden;
}
.utk-track {
    display: flex;
    align-items: center;
    white-space: nowrap;
    will-change: transform;
}
.utk-h-item {
    color: {{TITLE_COLOR}};
    font-size: {{TITLE_SIZE}}px;
    font-weight: {{TITLE_WEIGHT}};
    text-transform: {{TITLE_TRANSFORM}};
    padding: 0 20px;
    white-space: nowrap;
    display: inline-block;
}
.utk-sep {
    {{SEPARATOR_CSS}}
    display: inline-block;
    flex-shrink: 0;
}
/* ---- single-wrap (whip/vertical) ---- */
.utk-single-wrap {
    position: absolute; inset: 0;
    display: none;
    align-items: center;
    overflow: hidden;
    padding-left: 20px;
    box-sizing: border-box;
}
.utk-msg {
    color: {{TITLE_COLOR}};
    font-size: {{TITLE_SIZE}}px;
    font-weight: {{TITLE_WEIGHT}};
    text-transform: {{TITLE_TRANSFORM}};
    white-space: nowrap;
    opacity: 0;
    transition: opacity 0.38s ease;
    display: block;
    padding-top: {{PADDING_Y}}px;
    padding-bottom: {{PADDING_Y}}px;
}
.utk-msg.on { opacity: 1; }

