(() => {
    const ROOT = document.getElementById("{{ID}}");
    if (!ROOT) return;

    const ctn    = ROOT.querySelector('.utk-container');
    const wiper  = ROOT.querySelector('.utk-wiper');
    const wtxt   = ROOT.querySelector('.utk-wiper-text');
    const trkWrp = ROOT.querySelector('.utk-track-wrap');
    const trk    = ROOT.querySelector('.utk-track');
    const sngWrp = ROOT.querySelector('.utk-single-wrap');
    const msg    = ROOT.querySelector('.utk-msg');
    const dataEl = ROOT.querySelector('.utk-data');

    if (!ctn || !dataEl) { console.warn('[UTK] brak elementów'); return; }

    /* ---- parse items ---- */
    let items = [];
    const b64 = (dataEl.getAttribute('data-b64') || '').trim();
    if (b64) {
        try {
            const pad = b64 + '='.repeat((4 - b64.length % 4) % 4);
            const json = decodeURIComponent(escape(atob(pad)));
            items = JSON.parse(json);
        } catch(e) { console.error('[UTK] b64 error', e); }
    }
    if (!Array.isArray(items) || !items.length) items = [{text:'BRAK WIADOMOŚCI', category:''}];

    const getText = i => (i && typeof i === 'object') ? (i.text || '') : String(i);
    const getCat  = i => (i && typeof i === 'object') ? (i.category || '') : '';

    /* ---- settings ---- */
    const MODERAW  = '{{TICKER_MODE}}';
    const MODE     = (MODERAW && MODERAW !== 'undefined' && MODERAW !== 'false') ? MODERAW : 'whip';
    const WIPER_ON = '{{WIPER_SHOW}}' !== 'false';
    const SPEED    = parseFloat('{{TICKER_SPEED}}') || 100;
    const DEF_LBL  = ('{{WIPER_TEXT}}' || '').trim();

    /* ---- wiper ---- */
    function wiperW() { return wiper ? wiper.offsetWidth : 0; }

    function updateWiperVar() {
        const w = wiperW();
        ctn.style.setProperty('--wiper-w', w + 'px');
        sngWrp.style.paddingLeft = (w + 16) + 'px';
        return w;
    }

    let _lblTimer = null;
    function setLabel(lbl, immediate) {
        if (!wiper || !WIPER_ON) return;
        const l = (lbl || DEF_LBL || '').trim();
        if (!l) { wiper.style.display = 'none'; return; }
        wiper.style.display = 'flex';
        if (immediate || wtxt.textContent === l) { wtxt.textContent = l; updateWiperVar(); return; }
        if (_lblTimer) clearTimeout(_lblTimer);
        wtxt.style.opacity = '0';
        _lblTimer = setTimeout(() => {
            wtxt.textContent = l;
            wtxt.style.opacity = '1';
            updateWiperVar();
        }, 180);
    }

    /* ---- shared timers ---- */
    let _alive = false;
    let _timers = [];
    function t(fn, ms) { const id = setTimeout(() => { if (!_alive) return; fn(); }, ms); _timers.push(id); return id; }

    /* ============ TRYB: WHIP ============ */
    let _idx = 0;

    function whipNext() {
        if (!_alive) return;
        const item = items[_idx];
        msg.classList.remove('on');

        t(() => {
            setLabel(getCat(item), true);
            msg.innerHTML = getText(item);
            t(() => {
                msg.classList.add('on');
                // Trzymaj tekst 4s, potem ukryj i wysuń wiper w prawo
                t(() => {
                    msg.classList.remove('on');
                    t(() => {
                        // Wiper jedzie w prawo — przez klasę CSS (keyframe jest re-scopowany przez renderer)
                        wiper.className = 'utk-wiper utk-move-right';
                        const nextIdx = (_idx + 1) % items.length;
                        const nextCat = getCat(items[nextIdx]);
                        // W połowie drogi zmień etykietę
                        t(() => {
                            setLabel(nextCat, false);
                        }, 500);
                        // Po zakończeniu ruchu w prawo — wróć
                        t(() => {
                            wiper.className = 'utk-wiper utk-snap-back';
                            t(() => {
                                wiper.className = 'utk-wiper';
                                wiper.style.left = '0';
                                _idx = nextIdx;
                                whipNext();
                            }, 520);
                        }, 1020);
                    }, 380);
                }, 4000);
            }, 80);
        }, 60);
    }

    /* ============ TRYB: PIONOWY ============ */
    let _vIdx = 0;

    function vertNext() {
        if (!_alive) return;
        const item = items[_vIdx];
        msg.classList.remove('on');
        t(() => {
            setLabel(getCat(item), false);
            msg.innerHTML = getText(item);
            t(() => {
                msg.classList.add('on');
                const holdMs = Math.max(1500, SPEED * 1000);
                t(() => {
                    msg.classList.remove('on');
                    _vIdx = (_vIdx + 1) % items.length;
                    t(vertNext, 420);
                }, holdMs);
            }, 80);
        }, 60);
    }

    /* ============ TRYB: POZIOMY ============ */
    function startHorizontal() {
        trkWrp.style.display = 'flex';
        sngWrp.style.display = 'none';
        trk.innerHTML = '';
        const addBatch = () => items.forEach(item => {
            const s = document.createElement('span');
            s.className = 'utk-h-item';
            s.innerHTML = getText(item);
            trk.appendChild(s);
            const d = document.createElement('span');
            d.className = 'utk-sep';
            trk.appendChild(d);
        });
        addBatch(); addBatch();
        setLabel(getCat(items[0]), true);
        const pxPerSec = SPEED > 0 ? SPEED : 100;
        let x = 0, last = null;
        function tick(ts) {
            if (!_alive) return;
            if (last === null) last = ts;
            x += pxPerSec * ((ts - last) / 1000); last = ts;
            const half = trk.scrollWidth / 2;
            if (half > 0 && x >= half) x -= half;
            trk.style.transform = 'translateX(' + (-x) + 'px)';
            requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick);
    }

    /* ============ SHOW / HIDE ============ */
    ROOT.__slt_show = () => {
        _alive = true;
        if (MODE === 'horizontal') {
            trkWrp.style.display = 'flex';
            sngWrp.style.display = 'none';
        } else {
            trkWrp.style.display = 'none';
            sngWrp.style.display = 'flex';
        }
        const G = window.gsap;
        const run = () => {
            if (MODE === 'whip')       whipNext();
            else if (MODE === 'vertical')   vertNext();
            else if (MODE === 'horizontal') startHorizontal();
        };
        if (G) {
            const tl = CGMotion.standardIn(ctn, {{{ANIMATION_IN_JSON}}});
            tl.add(run);
            const lp = {{{LOOP_JSON}}};
            if (lp && lp.type && lp.type !== 'none') tl.add(() => CGMotion.loop(ctn, lp.type, lp));
        } else {
            ctn.style.opacity = '1'; ctn.style.transform = 'none'; run();
        }
    };

    ROOT.__slt_hide = () => {
        _alive = false;
        _timers.forEach(clearTimeout); _timers = [];
        if (_lblTimer) clearTimeout(_lblTimer);
        const G = window.gsap;
        if (G) {
            CGMotion.stopLoop(ctn);
            return CGMotion.standardOut(ctn, {{{ANIMATION_OUT_JSON}}});
        }
        ctn.style.opacity = '0';
    };
})();

